//! live floria integration tests for chime.}//!}//! These tests spawn a real `floria` push gateway binary on a loopback port,}//! drive chime's [`ContrixPushClient`] discovery flows + a raw}//! `cx.push.notify` POST against it, and assert the responses round-trip}//! through chime's wire types. They replace the four `rust,ignore` doctest}//! examples that previously stood in for live-server coverage.}//!}//! ## Skip semantics}//!}//! Each test silent-skips (returns `Ok(())` after a `eprintln!` breadcrumb)}//! when the floria binary is unavailable — see `_helpers/floria_spawn.rs`}//! for the precise pre-requisite contract. A red CI run should never block}//! on these tests; an operator who *wants* live coverage should:}//!}//! ```text}//! cd ../floria && cargo build --bin floria}//! cargo test --locked --all-features --test live_floria_integration}//! ```}//!}//! The four tests intentionally cover one layer each of the chime → floria}//! integration surface that the deleted doctests gestured at:}//!}//! 1. `bridge_describe_round_trips_against_live_floria` — replaces the}//!    `register_device_with_context` doctest by exercising the live discovery}//!    surface chime would consult **before** routing a register call.}//! 2. `integration_view_combines_describe_endpoints` — replaces the}//!    `register_device` retry-policy doctest by demonstrating the same}//!    `ContrixPushClient` end-to-end against a real listener (timeouts +}//!    retry policy + bearer token wired in for shape parity).}//! 3. `push_notify_delivery_receipt_round_trips_into_chime_wire_types` —}//!    replaces the request-signing doctest by sending an actual}//!    `cx.push.notify` request and asserting chime's}//!    [`PushNotifyResponse`] decodes the live floria reply.}//! 4. `repeated_notify_advances_floria_request_id` — replaces the token}//!    rotation doctest by treating each notify as a token-rotation analog}//!    (same payload twice, distinct request_ids, both accepted) which is the}//!    multi-gateway observability axis chime ultimately stores in}//!    [`PushRegistrationLastError`]-style records.}}#![cfg(all(feature = "http", feature = "notify"))]}}use std::time::Duration;}}use chime::{}    ContrixPushClient, PushNotifyResponse, PushRetryPolicy, push_bridge_describe_url,}    push_integration_describe_url,}};}use serde_json::{Value, json};}}#[path = "_helpers/floria_spawn.rs"]}mod floria_spawn;}}use floria_spawn::{SpawnedFloria, spawn_floria};}}const APP_ID: &str = "chime.live.placeholder";}const ORIGIN_DID: &str = "did:web:chime.live.test";}}/// Construct a `ContrixPushClient` against the spawned floria with all the}/// guards that fail-close in production but would block discovery calls in}/// tests (session grant requirement, retries) deliberately tuned down.}fn client_for(handle: &SpawnedFloria) -> ContrixPushClient {}    ContrixPushClient::new(handle.base_url.clone())}        // floria's anonymous notify_auth contract maps to "no session grant}        // needed" — disable the chime fail-closed default so discovery calls}        // can go through.}        .with_required_session_grant(false)}        .with_timeout(Duration::from_secs(5))}        .with_retry_policy(PushRetryPolicy::conservative())}}}}/// Minimal valid `cx.push.notify` payload in the current chime/floria wire}/// shape. The response deserializes into chime's [`PushNotifyResponse`], which}/// is the round-trip this integration test protects for SDK consumers.}fn notify_payload(idempotency_key: &str) -> Value {}    json!({}        "operation_id": chime::OPERATION_PUSH_NOTIFY,}        "idempotency_key": idempotency_key,}        "origin_service_did": ORIGIN_DID,}        "notification": {}            "event_id": "cx:event:01JS0EV000000000000000000",}            "message_id": "cx:message:01JS0MSG0000000000000000",}            "flow_id": "cx:flow:01JS0FLOW000000000000000",}            "space_id": "cx:space:01JS0SP000000000000000000",}            "push_target_id": "cx:pseudonym:push:01HYZ8Z000000000000000",}            "wakeup_kind": "message",}            "push_hint": "wakeup",}            "devices": [{}                "app_id": APP_ID,}                "push_key": "chime-live-token-01"}            }]}        }}    })}}}}#[tokio::test(flavor = "multi_thread")]}async fn bridge_describe_round_trips_against_live_floria() {}    let Some(floria) = spawn_floria().await else {}        eprintln!(}            "skip bridge_describe_round_trips_against_live_floria: floria binary unavailable"}        );}        return;}    };}}    let client = client_for(&floria);}    let response = client}        .bridge_describe()}        .await}        .expect("bridge_describe deserializes against live floria");}}    assert_eq!(response.contract, "cx.push.bridge.describe");}    assert_eq!(response.notify.notify_path, "/api/v1/push/notify");}    assert_eq!(response.notify.operation_id, chime::OPERATION_PUSH_NOTIFY);}    assert!(}        response}            .gateway}            .supported_providers}            .iter()}            .any(|p| p == APP_ID),}        "live floria should advertise the rendered placeholder app: {:?}",}        response.gateway.supported_providers}    );}}    // The chime SDK's URL helper should produce a URL that hits the same}    // endpoint we just successfully called — guards against `urls.rs` drift.}    let derived = push_bridge_describe_url(&floria.url("/api/v1/push/notify"))}        .expect("push_bridge_describe_url accepts the loopback gateway URL");}    assert_eq!(derived, floria.url("/api/v1/push/bridge/describe"));}}}}#[tokio::test(flavor = "multi_thread")]}async fn integration_view_combines_describe_endpoints() {}    let Some(floria) = spawn_floria().await else {}        eprintln!("skip integration_view_combines_describe_endpoints: floria binary unavailable");}        return;}    };}}    let client = client_for(&floria);}    let view = client}        .integration_view()}        .await}        .expect("integration_view round-trips against live floria");}}    // bridge contract identifier should appear in the manifest's required}    // contracts list — that wiring is what the doctest example tries to}    // demonstrate.}    let bridge_describe_present = view}        .manifest}        .surfaces}        .iter()}        .any(|s| s.path == "/api/v1/push/bridge/describe");}    assert!(}        bridge_describe_present,}        "integration manifest should advertise bridge/describe surface: {:?}",}        view.manifest.surfaces}    );}    assert_eq!(}        view.bridge.notify.operation_id,}        chime::OPERATION_PUSH_NOTIFY}    );}}    // SDK URL helper drift guard symmetric to bridge_describe test above.}    let derived = push_integration_describe_url(&floria.url("/api/v1/push/notify"))}        .expect("push_integration_describe_url accepts the loopback gateway URL");}    assert_eq!(derived, floria.url("/api/v1/integration/describe"));}}}}#[tokio::test(flavor = "multi_thread")]}async fn push_notify_delivery_receipt_round_trips_into_chime_wire_types() {}    let Some(floria) = spawn_floria().await else {}        eprintln!(}            "skip push_notify_delivery_receipt_round_trips_into_chime_wire_types: floria binary unavailable"}        );}        return;}    };}}    let http = reqwest::Client::builder()}        .timeout(Duration::from_secs(5))}        .build()}        .expect("reqwest client builds");}}    let response = http}        .post(floria.url("/api/v1/push/notify"))}        .json(&notify_payload("chime-live-notify-001"))}        .send()}        .await}        .expect("notify POST reaches floria");}    assert!(}        response.status().is_success(),}        "notify request returned {:?}",}        response.status()}    );}}    let raw = response}        .text()}        .await}        .expect("notify response body is readable");}    let parsed: PushNotifyResponse = serde_json::from_str(&raw)}        .unwrap_or_else(|err| panic!("chime PushNotifyResponse failed to decode {raw}: {err}"));}}    // Floria